import { NextResponse } from "next/server";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { KIRO_CONFIG } from "@/lib/oauth/constants/oauth";

/**
 * GET /api/oauth/kiro/social-authorize
 * Initiate Google/GitHub social login via device flow.
 * Returns a verification URL for the user to open in their browser.
 */
export async function GET(request) {
  const authResponse = await requireManagementAuth(request, { invalidApiKeyStatus: 401 });
  if (authResponse) return authResponse;

  try {
    const { searchParams } = new URL(request.url);
    const provider = searchParams.get("provider");

    if (!provider || !["google", "github"].includes(provider)) {
      return NextResponse.json(
        { error: "Invalid provider. Use 'google' or 'github'" },
        { status: 400 }
      );
    }

    const loginProvider = provider === "google" ? "Google" : "Github";

    const response = await fetch(KIRO_CONFIG.socialDeviceAuthorizeUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        clientId: KIRO_CONFIG.socialClientId,
        loginProvider,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      return NextResponse.json({ error: `Device authorization failed: ${error}` }, { status: 502 });
    }

    const data = await response.json();

    return NextResponse.json({
      authUrl: data.verificationUriComplete,
      deviceCode: data.deviceCode,
      userCode: data.userCode,
      expiresIn: Math.floor((data.expiresInMilliseconds || 300000) / 1000),
      interval: Math.floor((data.intervalInMilliseconds || 5000) / 1000),
      provider,
    });
  } catch (error) {
    console.error("Kiro social authorize error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { KiroService } from "@/lib/oauth/services/kiro";
import {
  createProviderConnection,
  getProviderConnections,
  updateProviderConnection,
  isCloudEnabled,
} from "@/models";
import { getConsistentMachineId } from "@/shared/utils/machineId";
import { syncToCloud } from "@/lib/cloudSync";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { validateBody, isValidationFailure } from "@/shared/validation/helpers";
import { KIRO_CONFIG } from "@/lib/oauth/constants/oauth";
import { findKiroConnectionByIdentity } from "@/lib/oauth/kiroConnectionIdentity";
import { classifyKiroSocialPoll } from "@/lib/oauth/kiroSocialPoll";

const socialExchangeSchema = z.object({
  deviceCode: z.string().min(1, "Missing deviceCode or provider"),
  provider: z.enum(["google", "github"]),
  targetProvider: z.enum(["kiro", "amazon-q"]).optional(),
});

/**
 * POST /api/oauth/kiro/social-exchange
 * Poll device code for tokens (Google/GitHub social login device flow).
 * Frontend calls this repeatedly until authorization completes.
 */
export async function POST(request: Request) {
  const authResponse = await requireManagementAuth(request, { invalidApiKeyStatus: 401 });
  if (authResponse) return authResponse;

  let rawBody;
  try {
    rawBody = await request.json();
  } catch {
    return NextResponse.json(
      {
        error: {
          message: "Invalid request",
          details: [{ field: "body", message: "Invalid JSON body" }],
        },
      },
      { status: 400 }
    );
  }

  const validation = validateBody(socialExchangeSchema, rawBody);
  if (isValidationFailure(validation)) {
    return NextResponse.json(
      { error: validation.error || "Missing deviceCode or provider" },
      { status: 400 }
    );
  }

  try {
    const { deviceCode, provider, targetProvider } = validation.data;

    const response = await fetch(KIRO_CONFIG.socialDevicePollUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ deviceCode, clientId: KIRO_CONFIG.socialClientId }),
    });

    const data = await response.json();
    const poll = classifyKiroSocialPoll(response.ok, response.status, data);

    if (poll.kind === "pending") {
      return NextResponse.json({
        success: false,
        pending: true,
        error: poll.error,
      });
    }

    if (poll.kind === "error") {
      return NextResponse.json(
        {
          success: false,
          pending: false,
          error: poll.error,
        },
        { status: poll.status }
      );
    }

    const kiroService = new KiroService();
    const email = kiroService.extractEmailFromJWT(data.accessToken);

    const providerSpecificData: Record<string, any> = {
      authMethod: "imported",
      provider: provider.charAt(0).toUpperCase() + provider.slice(1),
    };

    if (data.profileArn) {
      providerSpecificData.profileArn = data.profileArn;
    }

    const resolvedProvider = targetProvider || "kiro";
    const record = {
      accessToken: [REDACTED],
      refreshToken: [REDACTED],
      expiresAt: new Date(Date.now() + (data.expiresIn || 3600) * 1000).toISOString(),
      email: email || null,
      providerSpecificData,
      testStatus: "active",
      isActive: true,
    };
    const existing = await getProviderConnections({ provider: resolvedProvider });
    const match = findKiroConnectionByIdentity(existing, {
      authType: "oauth",
      profileArn: data.profileArn,
      email,
    });
    const connection: any =
      typeof match?.id === "string"
        ? await updateProviderConnection(match.id, record)
        : await createProviderConnection({
            provider: resolvedProvider,
            authType: "oauth",
            ...record,
          });

    await syncToCloudIfEnabled();

    return NextResponse.json({
      success: true,
      connection: {
        id: connection.id,
        provider: connection.provider,
        email: connection.email,
      },
    });
  } catch (error: any) {
    console.error("Kiro social exchange error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

async function syncToCloudIfEnabled() {
  try {
    const cloudEnabled = await isCloudEnabled();
    if (!cloudEnabled) return;
    const machineId = await getConsistentMachineId();
    await syncToCloud(machineId);
  } catch (error) {
    console.log("Error syncing to cloud after Kiro OAuth:", error);
  }
}

import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";

const REPO_ROOT = path.resolve(import.meta.dirname, "../..");

// #13679 item #9: docker-compose.yml has no top-level `networks:` key, so
// Compose puts every service (redis, qdrant, bifrost, cliproxyapi,
// codex-app-server, chatgpt-web-codex-browser, ...) on the same implicit
// default bridge network. The chatgpt-web-codex-browser sidecar exposes an
// UNAUTHENTICATED CDP proxy on 9223 (docker/chatgpt-web-codex-browser/cdp-proxy.mjs)
// — any compromised sibling container on that shared bridge can reach it and
// take full control of the live browser session. It must be isolated onto a
// dedicated network shared only with the one legitimate consumer
// (omniroute-web).

function readCompose(): string {
  return fs.readFileSync(path.join(REPO_ROOT, "docker-compose.yml"), "utf8");
}

function serviceBlock(compose: string, serviceName: string): string {
  const lines = compose.split("\n");
  const startIndex = lines.findIndex((line) => new RegExp(`^  ${serviceName}:\\s*$`).test(line));
  assert.notEqual(startIndex, -1, `service '${serviceName}' not found in docker-compose.yml`);
  const rest = lines.slice(startIndex + 1);
  const endOffset = rest.findIndex((line) => /^  \S/.test(line) || /^\S/.test(line));
  const block = endOffset === -1 ? rest : rest.slice(0, endOffset);
  return block.join("\n");
}

/**
 * The service's `networks:` entries, read line by line. A regex over the whole
 * block would need nested quantifiers (`(\s*-\s*.*\n)*`), which CodeQL flags as
 * a ReDoS risk (js/redos) — and the line walk is easier to read anyway.
 */
function listedNetworks(serviceYaml: string): string[] {
  const lines = serviceYaml.split("\n");
  const start = lines.findIndex((line) => /^\s*networks:\s*$/.test(line));
  if (start === -1) return [];
  const names: string[] = [];
  for (const line of lines.slice(start + 1)) {
    const item = line.match(/^\s*-\s*(\S+)\s*$/);
    if (!item) break;
    names.push(item[1]);
  }
  return names;
}

test("docker-compose.yml declares a dedicated network for the CDP proxy sidecar", () => {
  const compose = readCompose();
  assert.match(
    compose,
    /^networks:\s*$/m,
    "docker-compose.yml must declare a top-level `networks:` key — without it every " +
      "service shares the implicit default bridge, so any sibling container can reach " +
      "the unauthenticated chatgpt-web-codex-browser CDP proxy on 9223"
  );
});

test("chatgpt-web-codex-browser is isolated off the shared default network", () => {
  const compose = readCompose();
  const block = serviceBlock(compose, "chatgpt-web-codex-browser");
  assert.match(
    block,
    /networks:/,
    "chatgpt-web-codex-browser must declare an explicit `networks:` list — otherwise it " +
      "attaches to the implicit default network shared with redis/qdrant/bifrost/etc."
  );
  assert.ok(
    !listedNetworks(block).includes("default"),
    "chatgpt-web-codex-browser must not also list `default` — that would put it right back " +
      "on the shared bridge with every unrelated sibling container"
  );
});

test("omniroute-web (the one legitimate CDP consumer) stays reachable via the dedicated network", () => {
  const compose = readCompose();
  const block = serviceBlock(compose, "omniroute-web");
  assert.match(
    block,
    /networks:/,
    "omniroute-web must explicitly join the dedicated CDP-proxy network to keep reaching " +
      "chatgpt-web-codex-browser:9223 after the sidecar is isolated off the default network"
  );
});

test("unrelated sidecars (redis, qdrant) are not put on the CDP-proxy network", () => {
  const compose = readCompose();
  for (const serviceName of ["redis", "qdrant", "bifrost"]) {
    const block = serviceBlock(compose, serviceName);
    assert.doesNotMatch(
      block,
      /chatgpt-web-codex/,
      `${serviceName} must not reference the chatgpt-web-codex-browser network — it has no ` +
        "legitimate reason to reach the CDP proxy sidecar"
    );
  }
});

import test from "node:test";
import assert from "node:assert/strict";

// #4546 — In containers/headless, the system trust store can't be written
// (no sudo / read-only store / no interactive auth), so the cert install
// throws and used to abort the whole Agent Bridge start. These tests pin the
// graceful-fallback contract: a structured result that distinguishes a
// user-canceled auth from an environment failure, plus a platform-specific
// manual-install guide so the operator can trust the MITM root CA themselves.

const { classifyCertInstallError, buildCertManualGuide, installCertResult } = await import(
  "../../src/mitm/cert/install.ts"
);

const DOWNLOAD_URL = "/api/tools/agent-bridge/cert/download";

test("classifyCertInstallError → 'canceled' only when the message says canceled", () => {
  assert.equal(classifyCertInstallError("User canceled authorization"), "canceled");
  assert.equal(classifyCertInstallError("Operation was canceled by the user"), "canceled");
});

test("classifyCertInstallError → 'environment' for trust-store / sudo failures", () => {
  assert.equal(classifyCertInstallError("Certificate install failed"), "environment");
  assert.equal(classifyCertInstallError("sudo: no tty present and no askpass program specified"), "environment");
  assert.equal(classifyCertInstallError("Certificate file not found: /x/server.crt"), "environment");
});

test("buildCertManualGuide(linux) → update-ca-certificates steps + download url + cert path", () => {
  const guide = buildCertManualGuide("/data/mitm/server.crt", "linux");
  assert.equal(guide.platform, "linux");
  assert.equal(guide.certPath, "/data/mitm/server.crt");
  assert.equal(guide.downloadUrl, DOWNLOAD_URL);
  assert.ok(Array.isArray(guide.steps) && guide.steps.length > 0);
  const joined = guide.steps.join("\n");
  assert.ok(joined.includes("update-ca-"), "should mention the distro CA refresh command");
  assert.ok(joined.includes("/data/mitm/server.crt"), "should reference the cert path");
});

test("buildCertManualGuide(darwin) → security add-trusted-cert", () => {
  const guide = buildCertManualGuide("/d/server.crt", "darwin");
  assert.equal(guide.platform, "darwin");
  assert.ok(guide.steps.join("\n").includes("add-trusted-cert"));
});

test("buildCertManualGuide(win32) → certutil -addstore Root", () => {
  const guide = buildCertManualGuide("C:/d/server.crt", "win32");
  assert.equal(guide.platform, "win32");
  assert.ok(guide.steps.join("\n").toLowerCase().includes("certutil"));
});

test("installCertResult → environment skip (not a throw) when install is impossible", async () => {
  // A non-existent cert path makes installCert() throw before any privileged
  // command runs — deterministic, no sudo. The wrapper must convert that into a
  // structured skippable result with a manual guide, never a thrown error.
  const result = await installCertResult("", "/nonexistent/omniroute-4546-server.crt");
  assert.equal(result.installed, false);
  assert.equal(result.skipped, true);
  assert.equal(result.reason, "environment");
  assert.ok(result.manualGuide, "environment skip must carry a manual guide");
  assert.equal(result.manualGuide?.downloadUrl, DOWNLOAD_URL);
  // The message must be a safe string (no stack trace leaked).
  assert.equal(typeof result.message, "string");
  assert.ok(!String(result.message).includes("\n    at "), "must not leak a stack trace");
});

